import threading, time
from edge_sched import Scheduler, BackpressureError

s = Scheduler(workers=3, max_pending=5)
ran = {}
rlock = threading.Lock()
errors = []
elock = threading.Lock()

def fn(tid):
    def f():
        with rlock:
            assert tid not in ran, tid
            ran[tid] = True
        time.sleep(0.0005)
        return tid
    return f

N = 60
def batch_caller(i):
    size = (i % 5) + 1
    tids = ["b%d-%d" % (i, j) for j in range(size)]
    try:
        hs = s.submit_batch_with_wait(
            [{"task_id": t, "fn": fn(t)} for t in tids],
            admission_timeout_ms=20,
        )
        for h in hs: h.result(5)
    except BackpressureError:
        pass
    except Exception as e:
        with elock: errors.append((i, type(e).__name__))

def single_caller(i):
    try:
        s.submit_with_wait("s%d" % i, fn("s%d" % i), admission_timeout_ms=20)
    except BackpressureError:
        pass
    except Exception as e:
        with elock: errors.append((i, type(e).__name__))

ts = [threading.Thread(target=batch_caller, args=(i,)) for i in range(N)]
ts += [threading.Thread(target=single_caller, args=(i,)) for i in range(N)]
for t in ts: t.start()
for t in ts: t.join()
s.close()
snap = s.snapshot()
assert not errors, errors
assert snap.completed + snap.failed + snap.cancelled + snap.expired == snap.accepted, snap.to_dict()
assert len(ran) == snap.completed + snap.failed
print("ok", snap.accepted, "accepted,", snap.rejected, "rejected")
